(function () {
  'use strict';
  window.QUESTION_BANK = Object.assign(window.QUESTION_BANK || {}, {"grammar-singular-plural-nouns":{"title":"Singular and Plural Nouns","topic":"Grammar & Usage","questions":[{"id":"grammar-singular-plural-nouns-q0001","version":2,"contentHash":"sha256:b07f3682b0b81e8a5d3cec7c439471570abdc5b5421537adc8053b8ff6943314","question":"What is the plural of 'child'?","choices":["childs","children","childes","child"],"correct":1,"explanation":{"correct":"Answer: children. The word 'child' is an irregular noun, meaning it does not follow the standard rule of adding -s or -es to become plural.","incorrect":[{"choice":"childs","category":"incorrect plural suffix","reason":"Adding -s is the standard way to make most nouns plural, but 'child' is an irregular noun that follows its own special rule."},"",{"choice":"childes","category":"incorrect plural suffix","reason":"We add -es to words ending in sounds like -sh or -ch, but 'child' doesn't use this ending to become plural."},{"choice":"child","category":"singular form","reason":"The word 'child' refers to only one person. To talk about more than one, you must change the form of the word completely."}]},"studyAid":{"definition":"Irregular nouns are words that do not follow the normal rules to become plural and must be memorized individually.","example":"child/children, tooth/teeth, mouse/mice, person/people","strategyClue":"Think about how you would describe a group of kids at a playground; does the word change its ending or change its spelling entirely?","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":1,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0002","version":2,"contentHash":"sha256:23874e70eb62071f59be8ed0332fcc8f618333a85e49a1f79d50a21db6b97b32","question":"What is the plural of 'tooth'?","choices":["tooths","toothes","teeth","tooth"],"correct":2,"explanation":{"correct":"Answer: teeth. The word 'tooth' is an irregular noun that does not follow the standard rule of adding -s or -es. Instead, the middle vowels change to form the plural.","incorrect":[{"choice":"tooths","category":"incorrect pluralization","reason":"Adding -s is the rule for many nouns, but 'tooth' is an irregular noun. Using 'tooths' does not follow the special rule for this word."},{"choice":"toothes","category":"incorrect suffix usage","reason":"We add -es to words ending in sounds like -sh or -ch, but 'tooth' does not end that way. This is not the correct irregular form."},"",{"choice":"tooth","category":"singular noun","reason":"This is the singular form. Since the question asks for the plural, we need a word that represents more than one."}]},"studyAid":{"definition":"Irregular nouns are words that do not follow standard rules for forming plurals, such as adding -s or -es. You must memorize the unique plural form for each irregular word.","example":"foot -> feet, goose -> geese, mouse -> mice","strategyClue":"Ask yourself if the word sounds like a standard 's' plural. If it sounds strange, consider if it belongs to the special group of words that change their internal vowel sounds to become plural.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":2,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0003","version":2,"contentHash":"sha256:6ec4aa84227304b346c672c0dd5fc8abe4e70684affb8b125d7908a2301aba5b","question":"Which is the plural of 'deer'?","choices":["deers","deer","deeres","deeren"],"correct":1,"explanation":{"correct":"Answer: deer. Some nouns are irregular and do not change their form when they become plural. 'Deer' is one of these words, so it stays the same whether you are talking about one or many.","incorrect":[{"choice":"deers","category":"incorrect plural suffix","reason":"Adding an 's' to the end is the standard rule for many words, but it does not work for irregular nouns like 'deer'. 'Deers' is not a word found in the dictionary."},"",{"choice":"deeres","category":"incorrect plural suffix","reason":"Adding 'es' is a rule for words ending in sounds like 's', 'x', or 'ch'. This does not apply to 'deer' because it is an irregular noun."},{"choice":"deeren","category":"incorrect irregular plural","reason":"While some old English words add 'en' to make a plural, this does not apply to the word 'deer'. The correct plural form is simply 'deer'."}]},"studyAid":{"definition":"Some nouns are irregular and stay the same in both their singular and plural forms.","example":"one deer / five deer; one fish / ten fish; one sheep / many sheep","strategyClue":"Try saying the word in a sentence with a number before it, like 'I saw five ___.' If the word sounds unusual with an 's' or 'es' added, check if it belongs to the group of nouns that never change.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":3,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0004","version":2,"contentHash":"sha256:631a9252c7a23a449fe30ede1375e7fad2c5c5d55935dd644d1e557c21c24c34","question":"What is the plural of 'potato'?","choices":["potatos","potatoes","potato's","potatoes'"],"correct":1,"explanation":{"correct":"Answer: potatoes. Nouns ending in 'o' that are preceded by a consonant usually form their plural by adding '-es'.","incorrect":[{"choice":"potatos","category":"missing vowel","reason":"When a word ends in a consonant followed by 'o', you need to add '-es', not just '-s', to show it is plural."},"",{"choice":"potato's","category":"incorrect apostrophe usage","reason":"An apostrophe shows possession or a contraction, not a plural. Do not use an apostrophe when you are just talking about more than one potato."},{"choice":"potatoes'","category":"misplaced apostrophe","reason":"This shows ownership belonging to many potatoes. To simply state the plural of the noun, you do not need an apostrophe at all."}]},"studyAid":{"definition":"To make most nouns ending in a consonant plus 'o' plural, add '-es' to the end of the word.","example":"tomato -> tomatoes, hero -> heroes, potato -> potatoes","strategyClue":"Look at the letter right before the 'o'. If it is a consonant, remember to add the extra 'e' before the 's' to make it plural.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":4,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0005","version":2,"contentHash":"sha256:0fe0609566113bedd050331029e7f6e47ee838497057d36c516c7d4eb6d25c4d","question":"Which is the plural of 'knife'?","choices":["knifes","knives","knife's","knifves"],"correct":1,"explanation":{"correct":"Answer: knives. When a word ends in 'f' or 'fe', we often change the 'f' or 'fe' to 'ves' to make it plural.","incorrect":[{"choice":"knifes","category":"incorrect f ending","reason":"Simply adding an 's' doesn't work for words ending in 'fe'. We must change the ending to 'ves' to make it plural."},"",{"choice":"knife's","category":"possessive apostrophe error","reason":"An apostrophe shows ownership, not plurality. Adding 's is for a possessive, not for making a noun mean more than one."},{"choice":"knifves","category":"spelling error","reason":"This spelling incorrectly doubles the 'f' sound. The correct plural replaces the entire 'fe' sound with 'ves'."}]},"studyAid":{"definition":"To make many nouns ending in -f or -fe plural, change the 'f' or 'fe' to 'ves'.","example":"leaf -> leaves, wolf -> wolves, wife -> wives","strategyClue":"Cover the end of the noun and try to pronounce it with a 'v' sound before adding the final ending; this will help you distinguish between a simple 's' and the 'ves' rule.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":5,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0006","version":2,"contentHash":"sha256:19c8e4cffbddce7d57b08ad44a57a38dd68fe0cfdeb1ac94e60d3b98b927616b","question":"What is the plural of 'mouse'?","choices":["mouses","mice","mices","mouse's"],"correct":1,"explanation":{"correct":"Answer: mice. Most English nouns add 's' or 'es' to become plural, but 'mouse' is an irregular noun that completely changes its spelling to 'mice'.","incorrect":[{"choice":"mouses","category":"regular plural error","reason":"Adding 's' is the rule for regular nouns, but 'mouse' is an irregular noun. It does not follow the standard pattern of adding 's' or 'es'."},"",{"choice":"mices","category":"double pluralization","reason":"Since 'mice' is already the plural form, adding 's' to it creates an incorrect double plural. You never need to add an 's' to a word that is already plural."},{"choice":"mouse's","category":"possessive vs plural","reason":"An apostrophe followed by 's' shows possession (that something belongs to the mouse). It does not mean there is more than one mouse."}]},"studyAid":{"definition":"Irregular nouns are words that do not follow the normal rules to become plural and must be memorized individually.","example":"child -> children, foot -> feet, goose -> geese","strategyClue":"Think about whether the noun ends in a standard 's' or 'es' pattern. If the word sounds unusual when you add an 's', try to recall if it is an irregular noun that changes its middle vowel instead.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":6,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0007","version":2,"contentHash":"sha256:ae51685811119dab6a55a7a46d0cf72d71418d25129bc006be9118648cb251c1","question":"Which is the plural of 'box'?","choices":["boxs","boxes","box's","boxen"],"correct":1,"explanation":{"correct":"Answer: boxes. When a noun ends in -x, -s, -sh, -ch, or -z, you must add -es to make it plural instead of just adding -s.","incorrect":[{"choice":"boxs","category":"incorrect plural suffix","reason":"Simply adding -s is not enough for words ending in -x. You need to add -es to make the word sound correct and follow English spelling rules."},"",{"choice":"box's","category":"possessive versus plural","reason":"An apostrophe is used to show possession, meaning something belongs to the box. It should never be used to show that there is more than one of something."},{"choice":"boxen","category":"irregular plural error","reason":"While some old English words use -en to become plural, 'box' is a regular noun that follows the standard rule of adding -es."}]},"studyAid":{"definition":"To make most nouns ending in x, s, sh, ch, or z plural, you add -es to the end of the word.","example":"fox -> foxes, glass -> glasses, brush -> brushes, lunch -> lunches","strategyClue":"Look at the last letter of the word. If the word ends in a sound that makes it hard to say 's' immediately, consider if adding an 'e' makes it easier to pronounce.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":7,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0008","version":2,"contentHash":"sha256:3b6c129ddb8371a7c1c73e093a906ec04337010f46c9b479551cfaed7d8495c9","question":"What is the plural of 'cactus'?","choices":["cactuses","cacti","cactus","Both A and B"],"correct":3,"explanation":{"correct":"Answer: Both A and B. The word 'cactus' has two accepted plural forms in English: 'cactuses' follows standard English rules by adding '-es', and 'cacti' follows the original Latin root word pattern.","incorrect":[{"choice":"cactuses","category":"incomplete plural form","reason":"While 'cactuses' is a correct plural, it is not the *only* correct one. Both options provided are acceptable, so choosing only one misses half the answer."},{"choice":"cacti","category":"incomplete plural form","reason":"While 'cacti' is a widely used plural form based on Latin, 'cactuses' is also recognized as correct. Always check if more than one option is valid."},{"choice":"cactus","category":"singular noun form","reason":"The word 'cactus' is the singular form of the noun. Since the question asks for the plural, you need a word that describes more than one plant."},""]},"studyAid":{"definition":"Plural nouns indicate more than one person, place, or thing. While most nouns add '-s' or '-es', some words have special plural forms from other languages.","example":"dog/dogs, box/boxes, cactus/cactuses or cacti, focus/focuses or foci","strategyClue":"Check your dictionary or a list of irregular plurals to see if a word has a secondary, historical plural form in addition to the standard English version.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":8,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0009","version":2,"contentHash":"sha256:305e185928380039055b4f2ce301f296b33d9fb9dc992a81996f45e76b5750a6","question":"Which is the plural of 'sheep'?","choices":["sheeps","sheep","sheepes","sheep's"],"correct":1,"explanation":{"correct":"Answer: sheep. The word 'sheep' is an irregular noun that stays the same in both its singular and plural forms.","incorrect":[{"choice":"sheeps","category":"incorrect plural suffix","reason":"Adding an 's' is common for many nouns, but some special words like 'sheep' do not follow this rule. 'Sheeps' is not a word in English."},"",{"choice":"sheepes","category":"incorrect plural suffix","reason":"Adding 'es' is usually for nouns ending in sounds like 'ch' or 'sh', but 'sheep' is an irregular noun that doesn't change its spelling to become plural."},{"choice":"sheep's","category":"misused possessive apostrophe","reason":"The apostrophe is used to show ownership, not to make a word plural. 'Sheep's' would mean something belongs to the sheep."}]},"studyAid":{"definition":"Some nouns are irregular, meaning they do not use an 's' or 'es' to become plural. They may stay the same as the singular form or change completely.","example":"one sheep/two sheep, one fish/two fish, one mouse/two mice","strategyClue":"Look for words that represent animals or groups and test them in a sentence like 'I saw five ___.' If adding an 's' sounds unnatural, check if the word is an irregular noun that remains unchanged.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":9,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0010","version":2,"contentHash":"sha256:de7b46100406e2cc76917b90a1dc97ef4f62afc33e45a20d95c3a6f1ce3af7e3","question":"What is the plural of 'leaf'?","choices":["leafs","leaves","leafes","leaf's"],"correct":1,"explanation":{"correct":"Answer: leaves. Words ending in 'f' often change to 'ves' to become plural. Since 'leaf' ends in an 'f' sound, we drop the 'f' and add 'ves'.","incorrect":[{"choice":"leafs","category":"incorrect spelling rule","reason":"While some nouns ending in 'f' just add 's', the word 'leaf' follows the rule where the 'f' changes to 'v' before adding 'es'."},"",{"choice":"leafes","category":"incorrect plural suffix","reason":"This is a spelling error. The correct plural form requires changing the 'f' to a 'v' rather than just adding an extra 'e' to the end."},{"choice":"leaf's","category":"possessive vs plural","reason":"The apostrophe followed by an 's' shows possession, meaning something belongs to the leaf. To make the word plural, simply change the ending without using an apostrophe."}]},"studyAid":{"definition":"Many nouns ending in 'f' or 'fe' change the 'f' to a 'v' and add 'es' to become plural.","example":"leaf/leaves, knife/knives, shelf/shelves, life/lives","strategyClue":"Try saying the word aloud in its plural form. Listen to see if the ending sound changes from a sharp 'f' to a softer 'v' sound, which is a strong hint that you need a 'v' spelling.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":10,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0011","version":2,"contentHash":"sha256:77c5a94fc10013ff7a936f4d9604a82be646ab42f797f36dd4e4ab54c6b1fd40","question":"Which is the plural of 'octopus'?","choices":["octopuses","octopi","octopodes","All are accepted"],"correct":3,"explanation":{"correct":"Answer: All are accepted. While 'octopuses' is the standard English plural, 'octopi' is widely used due to Latin influence, and 'octopodes' is the historically correct Greek form. All three are recognized in modern dictionaries.","incorrect":[{"choice":"octopuses","category":"common plural form","reason":"This is a correct form! It follows the standard English rule of adding '-es' to words ending in 's'. It is not incorrect, as the question asks for all valid plural forms."},{"choice":"octopi","category":"Latin-based plural","reason":"This is a correct form! Although linguists originally debated the origin of the word, 'octopi' has been used for centuries and is now accepted in most English dictionaries."},{"choice":"octopodes","category":"Greek-based plural","reason":"This is a correct form! Because the word 'octopus' comes from Greek, using the Greek plural ending '-odes' is technically accurate, even if it sounds unusual to some speakers."},""]},"studyAid":{"definition":"Some words have more than one correct plural form because they come from different languages or have changed over time.","example":"cactus (cactuses or cacti), focus (focuses or foci), octopus (octopuses, octopi, or octopodes)","strategyClue":"Check if a word's plural has been influenced by both Latin and Greek roots; when in doubt, check if a reliable dictionary recognizes multiple forms as standard.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":11,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0012","version":2,"contentHash":"sha256:77127bf20d5676e06bb0e9ec5a16fc9a1849feea91bd2aeec382f1238898f94f","question":"What is the plural of 'woman'?","choices":["womans","women","womens","woman's"],"correct":1,"explanation":{"correct":"Answer: women. 'Woman' is an irregular noun that changes its vowel sound and spelling in the plural form rather than simply adding -s or -es.","incorrect":[{"choice":"womans","category":"incorrect plural spelling","reason":"Simply adding an 's' to the end of 'woman' is incorrect because it is an irregular noun. Irregular nouns have special plural forms that you must memorize."},"",{"choice":"womens","category":"double plural error","reason":"This is incorrect because 'women' is already the plural form of 'woman'. Adding an 's' to 'women' is redundant and not standard English."},{"choice":"woman's","category":"possessive vs plural","reason":"The apostrophe here makes the word possessive (showing ownership), not plural. To show there is more than one woman, use the irregular plural form."}]},"studyAid":{"definition":"Irregular nouns are words that do not follow the standard rule of adding -s or -es to become plural; they change their spelling instead.","example":"man to men, woman to women, child to children, foot to feet.","strategyClue":"Think about how we say the plural of 'man'. Since 'woman' contains the word 'man', the plural spelling follows the same pattern.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":12,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0013","version":2,"contentHash":"sha256:33fb96588d7f5fe6e395cdd60eb78632e8007d9d83414423a520b7eb133a2a94","question":"Which is the plural of 'crisis'?","choices":["crisises","crises","crisis","crisis'"],"correct":1,"explanation":{"correct":"Answer: crises. Words ending in '-is' often change to '-es' in the plural form. This is an irregular plural pattern used for words borrowed from ancient languages.","incorrect":[{"choice":"crisises","category":"incorrect pluralization","reason":"You cannot add '-es' to the end of a word that already ends in 's' in this way. Irregular words like 'crisis' follow specific spelling patterns rather than just adding an 's'."},"",{"choice":"crisis","category":"singular noun","reason":"This is the singular form of the word. Since the question asks for the plural, we need a word that describes more than one."},{"choice":"crisis'","category":"possessive noun","reason":"The apostrophe is used to show ownership, not to make a word plural. Avoid using apostrophes unless the word shows that something belongs to the noun."}]},"studyAid":{"definition":"Some English words that end in '-is' change their ending to '-es' to become plural.","example":"crisis -> crises, thesis -> theses, basis -> bases","strategyClue":"Look for words that share the same '-is' ending. If you recognize the pattern of changing the last two letters, apply that same rule to the current word.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":13,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0014","version":2,"contentHash":"sha256:32c95e27906a7451ed2fa73186651fbd5b5fcff450e0b3fe3421ae5a7574b6df","question":"What is the plural of 'piano'?","choices":["pianos","pianoes","pianoes'","piano's"],"correct":0,"explanation":{"correct":"Answer: pianos. For most words ending in 'o' preceded by a vowel, or for musical terms ending in 'o', we simply add an 's' to make them plural.","incorrect":["",{"choice":"pianoes","category":"incorrect plural spelling","reason":"Adding '-es' is common for many words ending in 'o', but 'piano' is an exception. It follows the rule for musical instruments, which take an 's' instead."},{"choice":"pianoes'","category":"apostrophe usage error","reason":"Apostrophes are for showing possession, not for making a noun plural. Adding an apostrophe here creates a possessive form that doesn't fit the sentence."},{"choice":"piano's","category":"possessive noun error","reason":"This form shows possession (like 'the piano's keys'), not the plural of the word. Remove the apostrophe to show there is more than one piano."}]},"studyAid":{"definition":"To make most nouns plural, you add '-s' or '-es' to the end of the word. Some words that end in 'o' are special and only take an 's'.","example":"cat -> cats, box -> boxes, piano -> pianos, solo -> solos","strategyClue":"Think about how the word sounds when you say it out loud. For many musical terms ending in 'o', try adding just the letter 's' first to see if it follows the pattern for musical instruments.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":14,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0015","version":2,"contentHash":"sha256:ec62c4d5ed40bd04531025118694cbf415b91394adf67966b50043acda47f953","question":"Which is the plural of 'radius'?","choices":["radiuses","radii","radius","Both A and B"],"correct":3,"explanation":{"correct":"Answer: Both A and B. Both 'radiuses' and 'radii' are accepted plural forms of 'radius'. 'Radii' is more common in mathematics and science, while 'radiuses' is also considered correct in standard English.","incorrect":[{"choice":"radiuses","category":"incomplete answer","reason":"While this is a correct plural form, it is not the *only* correct choice because 'radii' is also widely accepted."},{"choice":"radii","category":"incomplete answer","reason":"While this is a standard plural form, it is not the *only* correct choice because 'radiuses' is also considered a correct plural."},{"choice":"radius","category":"singular noun form","reason":"The word 'radius' is the singular form. To show more than one, you must change the word using one of the plural endings."},""]},"studyAid":{"definition":"Nouns that come from Latin often have special plural endings, but some also follow regular English rules by adding '-es'.","example":"cactus: cacti or cactuses; focus: foci or focuses; radius: radii or radiuses","strategyClue":"Check your dictionary for words ending in '-us'. Often, these words have a scientific plural ending in '-i' as well as a regular plural ending in '-es'.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":15,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0016","version":2,"contentHash":"sha256:9149d8f7e1cc2762b23dfe3e088d7b96e75d26de3f2136414785b02cdc084d07","question":"Which choice is a plural noun made by adding -es?","choices":["dancing","dishes","danced","slipper"],"correct":1,"explanation":{"correct":"Answer: dishes. Words ending in -sh, -ch, -s, -x, or -z need to have -es added to the end to make them plural.","incorrect":[{"choice":"dancing","category":"verb participle","reason":"This is a verb form ending in -ing, not a plural noun. It describes an action rather than naming more than one object."},"",{"choice":"danced","category":"past tense verb","reason":"This is a verb in the past tense. Adding -ed to a word shows an action that already happened, not that there is more than one object."},{"choice":"slipper","category":"singular noun","reason":"This is a singular noun. To make it plural, you would add an -s, not -es, because it ends in an 'r' sound."}]},"studyAid":{"definition":"To make most nouns plural, add -s. If a noun ends in -sh, -ch, -s, -x, or -z, you must add -es to make it plural.","example":"bus -> buses, box -> boxes, church -> churches","strategyClue":"Look at the last two letters of each word. If the word ends in a sound like 'sh' or 'ch', count those as a special group that needs the longer ending.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":16,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0017","version":2,"contentHash":"sha256:a11b97f7f07a29fd0c9680a31b79b3a7db989175cdc5bb70af44926772750db5","question":"Singular or plural? cracker","choices":["singular","plural","possessive","proper"],"correct":0,"explanation":{"correct":"Answer: singular. The word 'cracker' refers to one single object, making it a singular noun.","incorrect":["",{"choice":"plural","category":"number disagreement","reason":"The word 'cracker' does not have an 's' or 'es' ending to show there is more than one. A plural noun would be 'crackers'."},{"choice":"possessive","category":"missing apostrophe","reason":"Possessive nouns show ownership and usually include an apostrophe, like 'cracker's'. Since this word has no punctuation, it is not possessive."},{"choice":"proper","category":"incorrect noun type","reason":"Proper nouns name specific people, places, or brands and start with capital letters. 'Cracker' is a common noun used for any cracker."}]},"studyAid":{"definition":"A singular noun refers to just one person, place, or thing, while a plural noun refers to more than one.","example":"Singular: cat, boy, box. Plural: cats, boys, boxes.","strategyClue":"Ask yourself: 'If I was holding this item in my hand, would I be holding one or many?' If it is just one, choose the singular label.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":17,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0018","version":2,"contentHash":"sha256:d0a209d8044b5e20eeeca6ce018d30dddd9a81acb4157c85553f1db190b38101","question":"Singular or plural noun? dolphin","choices":["singular","plural","possessive","proper"],"correct":0,"explanation":{"correct":"Answer: singular. A singular noun names only one person, place, or thing. Since 'dolphin' refers to just one creature without an 's' at the end, it is singular.","incorrect":["",{"choice":"plural","category":"plural noun identification","reason":"Plural nouns usually end in 's' or 'es' to show there is more than one. Because 'dolphin' does not have an ending that shows more than one, it is not plural."},{"choice":"possessive","category":"possessive noun identification","reason":"Possessive nouns show ownership and require an apostrophe, like 'dolphin's'. Since this word has no apostrophe, it is not possessive."},{"choice":"proper","category":"proper noun identification","reason":"Proper nouns are specific names that start with a capital letter, like 'Flipper'. Since 'dolphin' is a common noun and starts with a lowercase letter, it is not a proper noun."}]},"studyAid":{"definition":"A singular noun names one person, place, or thing, while a plural noun names more than one. Most plural nouns are formed by adding -s or -es to the end of the singular word.","example":"Singular: cat, dog, box. Plural: cats, dogs, boxes.","strategyClue":"Ask yourself if the word represents only one item. If it doesn't end in 's' or 'es' and describes a single member of a group, label it as singular.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":18,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0019","version":2,"contentHash":"sha256:b8b92e7069102f0f8ea60466e41a82a2fdc05f5fe3e47adce5a2881a666d6401","question":"Singular or plural noun? children","choices":["singular","plural","possessive","proper"],"correct":1,"explanation":{"correct":"Answer: plural. The word 'children' is the plural form of the singular noun 'child', as it refers to more than one person.","incorrect":[{"choice":"singular","category":"noun number","reason":"Singular nouns refer to only one person, place, or thing. 'Children' refers to a group, so it cannot be singular."},"",{"choice":"possessive","category":"possessive noun error","reason":"A possessive noun shows ownership and typically includes an apostrophe (e.g., 'children's'). 'Children' does not show ownership here."},{"choice":"proper","category":"noun classification","reason":"Proper nouns name specific people or places and are always capitalized (e.g., 'Sam'). 'Children' is a common noun that describes a group."}]},"studyAid":{"definition":"A singular noun names one person, place, or thing, while a plural noun names more than one. Many nouns become plural by adding 's' or 'es', but some are irregular and change their spelling entirely.","example":"Singular: cat, child, tooth. Plural: cats, children, teeth.","strategyClue":"Ask yourself: 'Does this word name one person or more than one?' If you can imagine more than one person being described by the word, it is likely plural.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":19,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0020","version":2,"contentHash":"sha256:e26009a8aac44896fec08512dd2bed298c1488777af34b40fca50c03b0f55675","question":"Which choice is a singular noun?","choices":["crackers","dolphins","child","keys"],"correct":2,"explanation":{"correct":"Answer: child. A singular noun refers to only one person, place, or thing. 'Child' represents one individual, making it singular.","incorrect":[{"choice":"crackers","category":"plural noun ending","reason":"The '-s' at the end of 'crackers' indicates that there is more than one. Because it represents a group, it is a plural noun, not singular."},{"choice":"dolphins","category":"plural noun ending","reason":"The word 'dolphins' includes an '-s' to show that there are multiple animals, so it is a plural noun rather than a singular one."},"",{"choice":"keys","category":"plural noun ending","reason":"Adding an '-s' to 'key' makes it 'keys', which means more than one. Therefore, this is a plural noun, not a singular one."}]},"studyAid":{"definition":"A singular noun names just one person, place, or thing. A plural noun names more than one, usually by adding 's' or 'es' to the end.","example":"Singular: cat, boy, dish. Plural: cats, boys, dishes.","strategyClue":"Try to put the number 'one' in front of each word. If the word still sounds natural when paired with 'one,' it is likely a singular noun.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":20,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0021","version":2,"contentHash":"sha256:7367b96af6f64b5ac9d5db5030fea557fb7a46075ba1af14e172603fce351507","question":"Singular or plural? keys","choices":["singular","plural","possessive","proper"],"correct":1,"explanation":{"correct":"Answer: plural. The word 'keys' ends in 's' and refers to more than one object, which is the definition of a plural noun.","incorrect":[{"choice":"singular","category":"noun quantity","reason":"Singular nouns refer to only one object, like 'key'. Since 'keys' indicates more than one, it cannot be singular."},"",{"choice":"possessive","category":"noun function","reason":"Possessive nouns show ownership, usually with an apostrophe (e.g., 'key's'). 'Keys' is just a plural noun, not a possessive one."},{"choice":"proper","category":"noun type","reason":"Proper nouns name specific people, places, or things and are always capitalized, such as 'London' or 'John'. 'Keys' is a common noun."}]},"studyAid":{"definition":"A singular noun names one person, place, or thing, while a plural noun names more than one. Most nouns are made plural by adding 's' or 'es' to the end.","example":"Singular: cat, box; Plural: cats, boxes","strategyClue":"Ask yourself if you could hold just one of these items in your hand to see if the word represents a single object or a group of many.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":21,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0022","version":2,"contentHash":"sha256:400317d7526c49077b90df3f2b68f36aadb3648d8bcdeb296ce2da465dda6774","question":"Singular or plural? family","choices":["singular","plural","possessive","proper"],"correct":0,"explanation":{"correct":"Answer: singular. A 'family' refers to a single group of people acting as one unit. Even though it contains multiple individuals, the word itself represents one collective noun in its singular form.","incorrect":["",{"choice":"plural","category":"collective noun confusion","reason":"While a family is made up of several people, the word 'family' is the singular form. To make it plural, you would need to change it to 'families'."},{"choice":"possessive","category":"form vs function","reason":"The word 'family' does not have an apostrophe or an 's' at the end to show ownership, so it is not a possessive noun."},{"choice":"proper","category":"common noun type","reason":"'Family' is a common noun because it refers to a general group, not a specific, unique name of a person, place, or thing that would require a capital letter."}]},"studyAid":{"definition":"A singular noun refers to one person, place, or thing, while a plural noun refers to more than one. Collective nouns like 'family' describe a group and are treated as singular unless the group members are acting separately.","example":"Singular: family, team, class. Plural: families, teams, classes.","strategyClue":"Ask yourself if the word refers to one group or if it already has a plural ending like '-s' or '-ies'. If it stands for one single unit and lacks a plural suffix, it is singular.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":22,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0023","version":2,"contentHash":"sha256:a00c0075dcb06fff5197bcea119347e8d9d99050786b08944fe001c93ea2dc47","question":"What is the plural form of 'party'?","choices":["partys","parties","party's","partyes"],"correct":1,"explanation":{"correct":"Answer: parties. When a word ends in a consonant plus 'y', change the 'y' to 'i' and add 'es' to make it plural.","incorrect":[{"choice":"partys","category":"incorrect spelling rule","reason":"Simply adding 's' to a word ending in a consonant + 'y' is not enough. You must change the 'y' to 'i' first."},"",{"choice":"party's","category":"possessive versus plural","reason":"An apostrophe shows possession or ownership, like 'the party's music.' It does not make a word plural."},{"choice":"partyes","category":"incorrect suffix rule","reason":"Adding 'es' without changing the 'y' to 'i' does not follow the standard English rule for words ending in a consonant and 'y'."}]},"studyAid":{"definition":"To make a word ending in a consonant plus 'y' plural, drop the 'y' and add 'ies'.","example":"city -> cities, fly -> flies, puppy -> puppies","strategyClue":"Look at the letter right before the 'y'. If it is a consonant, use the 'i-e-s' rule instead of just adding an 's'.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":23,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0024","version":2,"contentHash":"sha256:3f442069a31c4e20a9ef47b44308fff88a247cdad9609cfaa10e198b2fba2e40","question":"What is the plural form of 'family'?","choices":["familys","families","family's","familys'"],"correct":1,"explanation":{"correct":"Answer: families. When a word ends in a consonant plus 'y', you must drop the 'y' and add '-ies' to make it plural.","incorrect":[{"choice":"familys","category":"incorrect plural spelling","reason":"Simply adding an 's' to the end doesn't follow the rule for words ending in 'y'. You must remove the 'y' first."},"",{"choice":"family's","category":"possessive versus plural","reason":"The apostrophe makes the word possessive, meaning something belongs to the family. Use this for ownership, not for more than one family."},{"choice":"familys'","category":"incorrect plural possessive","reason":"This is a possessive form for a plural noun, but it also incorrectly keeps the 'y' instead of using the 'ies' ending required for the plural form."}]},"studyAid":{"definition":"To make a noun plural when it ends in a consonant followed by 'y', drop the 'y' and add 'ies'.","example":"city -> cities, berry -> berries, family -> families","strategyClue":"Look at the letter right before the 'y'. If it is a consonant, remember to swap the 'y' for 'i' before adding your ending.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":24,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0025","version":2,"contentHash":"sha256:d73565aeebbaf6712eb43106998e9b18e04dacd6b3d87e1553ab1afbacabf99d","question":"What is the plural form of 'class'?","choices":["classes","classs","class's","classies"],"correct":0,"explanation":{"correct":"Answer: classes. When a word ends in the letters 's', 'ss', 'sh', 'ch', or 'x', you must add '-es' to the end to make it plural.","incorrect":["",{"choice":"classs","category":"incorrect spelling","reason":"Simply adding an 's' to words that already end in 'ss' makes them hard to say. Following the '-es' rule keeps the word easy to read and pronounce."},{"choice":"class's","category":"apostrophe misuse","reason":"An apostrophe followed by an 's' shows possession, meaning something belongs to the class. It is not used for making nouns plural."},{"choice":"classies","category":"incorrect pluralization","reason":"The '-ies' ending is used for words that end in a consonant followed by a 'y', such as 'baby' becoming 'babies'. It does not apply to words ending in 'ss'."}]},"studyAid":{"definition":"To make a noun that ends in 's', 'ss', 'ch', 'sh', or 'x' plural, add '-es' to the end of the word.","example":"bus -> buses, box -> boxes, match -> matches","strategyClue":"Look at the last two letters of the singular noun. If the word ends in a 'hissing' sound or an 'x', test adding '-es' instead of just '-s'.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":25,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0026","version":2,"contentHash":"sha256:4f7d3c7c7fdf0927a57ab32b4bdab356e06aa9854313ee20fa6f51b0c0c96d79","question":"What is the plural form of 'box'?","choices":["boxs","boxies","boxes","box's"],"correct":2,"explanation":{"correct":"Answer: boxes. When a word ends in -x, -s, -sh, -ch, or -z, you must add -es to the end to make it plural.","incorrect":[{"choice":"boxs","category":"incorrect plural suffix","reason":"Adding only an -s does not work for words ending in -x. You need to add -es to make the sound clear and correct."},{"choice":"boxies","category":"incorrect suffix spelling","reason":"Adding -ies is used for words that end in a consonant followed by a 'y', such as 'puppy' becoming 'puppies'. It is not the rule for words ending in -x."},"",{"choice":"box's","category":"apostrophe usage error","reason":"Adding an apostrophe creates a possessive form (something belonging to the box), not a plural form. Plurals never use apostrophes."}]},"studyAid":{"definition":"To make most words that end in x, s, sh, ch, or z plural, you add -es instead of just -s.","example":"fox -> foxes, bus -> buses, brush -> brushes","strategyClue":"Look at the very last letter of the word. If it is one of the 'hissing' or 'sharp' sounds like x, s, or ch, remember to add that extra syllable with -es.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":26,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0027","version":2,"contentHash":"sha256:4486f5f4ee97d1dac098610e02146a6f27eb2aeca44fa8cd889ea0af8ba1fd42","question":"Which label best describes tooth's in 'the tooth's color'?","choices":["singular possessive","plural possessive","plural noun","proper noun"],"correct":0,"explanation":{"correct":"Answer: singular possessive. The word 'tooth's' shows that one tooth owns the color. Adding an apostrophe followed by 's' indicates that a singular noun owns something.","incorrect":["",{"choice":"plural possessive","category":"incorrect number","reason":"Plural possessives usually end in 's' followed by an apostrophe (e.g., teeth's or if plural, teeth's is not used this way, as teeth is already plural). Since 'tooth' is a single object, it cannot be a plural possessive."},{"choice":"plural noun","category":"number error","reason":"A plural noun refers to more than one, like 'teeth'. Because there is an apostrophe and an 's', it shows possession, not just a plural count."},{"choice":"proper noun","category":"naming convention error","reason":"A proper noun is a specific name like 'Rover' or 'London' that gets a capital letter. 'Tooth' is a common noun because it names a general body part."}]},"studyAid":{"definition":"A singular possessive noun shows that one person, place, or thing owns something by adding an apostrophe and an 's' to the end of the word.","example":"the dog's toy (one dog), the car's wheel (one car), the book's cover (one book)","strategyClue":"First, count how many items are being discussed, then check if the word is being used to show ownership or just to name an object.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":27,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0028","version":2,"contentHash":"sha256:6681e352d6b77d14d161d142ab3491e717a484cc4e5e1e7621e63be75dfaa0ad","question":"Which label best describes babies' in 'the babies' cries'?","choices":["singular possessive","plural possessive","singular noun","proper noun"],"correct":1,"explanation":{"correct":"Answer: plural possessive. The word 'babies' refers to more than one baby, and the apostrophe placed after the 's' indicates that the cries belong to all those babies.","incorrect":[{"choice":"singular possessive","category":"wrong possessive form","reason":"A singular possessive would be written as 'baby's' with the apostrophe before the 's'. Since this is 'babies'', it refers to multiple babies, not just one."},"",{"choice":"singular noun","category":"incorrect number form","reason":"A singular noun is just one person, place, or thing. 'Babies' ends in 'ies' because it is plural; a singular noun would simply be 'baby'."},{"choice":"proper noun","category":"not a proper noun","reason":"Proper nouns name specific people or places and are always capitalized. 'Babies' is a common noun because it refers to any baby in general."}]},"studyAid":{"definition":"A plural possessive noun shows that something belongs to a group of two or more, usually formed by adding an apostrophe after the plural 's'.","example":"the dogs' bowls (many dogs), the kids' toys (many kids), the cat's bowl (one cat)","strategyClue":"Look at where the apostrophe is placed in relation to the 's'. Check if the base word shows one or many, and see if the apostrophe is at the very end of the plural form.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":28,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0029","version":2,"contentHash":"sha256:eea4097c0e63ee1dae665b67d157bdefd9f76f3bb71f0161fefb0d2fe48c247b","question":"What is the plural form of 'puppy'?","choices":["puppys","puppies","puppy's","puppyes"],"correct":1,"explanation":{"correct":"Answer: puppies. When a word ends in a consonant followed by 'y', you change the 'y' to 'i' and add 'es' to make it plural.","incorrect":[{"choice":"puppys","category":"incorrect y ending","reason":"Simply adding an 's' keeps the 'y' in the word. When a noun ends in a consonant + y, you must change that 'y' to 'i' first."},"",{"choice":"puppy's","category":"possessive vs plural","reason":"An apostrophe followed by an 's' shows ownership, not plurality. You do not need an apostrophe to talk about more than one puppy."},{"choice":"puppyes","category":"incorrect spelling rule","reason":"Adding 'es' directly to the word keeps the 'y' and adds an extra letter. Remember to replace the 'y' with 'i' before adding the 'es' ending."}]},"studyAid":{"definition":"To make most nouns that end in a consonant plus 'y' plural, drop the 'y' and add 'ies'.","example":"city -> cities, baby -> babies, puppy -> puppies","strategyClue":"Look at the letter right before the 'y'. If it is a consonant, use your rule to replace the 'y' with 'ies' instead of just adding an 's'.","link":"https://www.grammar-monster.com/glossary/plural.htm","linkText":"Grammar Monster - Plurals"},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":29,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-singular-plural-nouns-q0030","version":2,"contentHash":"sha256:fcbb12f5bfd24a95969b870e3efcadd5325c5d31a5ae9fab8d81b53e814ef14c","question":"Identify the basic sentence pattern in the sentence below. The wolves whined and howled.","choices":["noun - verb - verb","noun - verb - adverb","noun - linking verb - adjective","noun - verb - noun"],"correct":0,"explanation":{"correct":"Answer: noun - verb - verb. The word 'wolves' is the noun acting as the subject. 'Whined' and 'howled' are both action verbs describing what the wolves did.","incorrect":["",{"choice":"noun - verb - adverb","category":"incorrect word classification","reason":"An adverb would describe how or when the action happened, such as 'quietly.' 'Howled' is an action word, which makes it a verb, not an adverb."},{"choice":"noun - linking verb - adjective","category":"incorrect sentence pattern","reason":"Linking verbs like 'is' or 'seem' connect a noun to a description. 'Whined' and 'howled' are active movements, making them action verbs, not linking verbs."},{"choice":"noun - verb - noun","category":"missing sentence object","reason":"A 'noun' after the verb would be the object receiving the action. In this sentence, there is no object receiving the howling; there is simply a second action verb."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":30,"sourceFile":"Advanced-1_grammer and usage.pdf","sourceQuestionNumber":2,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"A sentence pattern describes the order and types of words used. Action verbs show what a subject does, and a compound predicate uses two verbs joined by a conjunction.","example":"Birds fly (noun - verb). Birds fly and sing (noun - verb - verb). Birds are beautiful (noun - linking verb - adjective).","strategyClue":"Label each word in the sentence as a person/place/thing or an action. If you find two action words connected by 'and' without an object, look for the pattern that lists two verbs.","link":"","linkText":""}},{"id":"grammar-singular-plural-nouns-q0031","version":2,"contentHash":"sha256:45381b323949f0152a44c8a345d9dab48e2c36964d3a114225d2e924226e9bec","question":"Choose the correct sentence.","choices":["One of the policemen are employed by the state.","All of the policemen are employed by the state.","Each of the policemen are employed by the state.","Not one of the policemen are employed by the state."],"correct":1,"explanation":{"correct":"Answer: All of the policemen are employed by the state. The subject 'All' is plural, so it correctly agrees with the plural verb 'are'.","incorrect":[{"choice":"One of the policemen are employed by the state.","category":"subject-verb disagreement","reason":"The word 'One' is singular. When using 'One of', the verb must be singular ('is'), not plural ('are')."},"",{"choice":"Each of the policemen are employed by the state.","category":"subject-verb disagreement","reason":"The word 'Each' acts as a singular subject. Even though there are many policemen, 'Each' requires the singular verb 'is'."},{"choice":"Not one of the policemen are employed by the state.","category":"subject-verb disagreement","reason":"The phrase 'Not one' is singular. Like 'One' or 'Each', it requires the singular verb 'is' rather than the plural 'are'."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":31,"sourceFile":"Advanced-1_grammer and usage.pdf","sourceQuestionNumber":6,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Some subjects like 'each', 'one', and 'everyone' are always singular and need a singular verb, while 'all' can be plural when it refers to a group.","example":"Each student is ready. / All students are ready. / One of the cats is sleeping.","strategyClue":"Identify the head noun or pronoun acting as the subject before the 'of' phrase. If the subject word is singular, use a singular verb ending in 's' or 'is'; if it is plural, use 'are'.","link":"","linkText":""}},{"id":"grammar-singular-plural-nouns-q0032","version":3,"contentHash":"sha256:90af3248a677f4a0da8a30743a86fdd0a1e64a08ba760bfa13e734a33697ad72","question":"Which noun is NOT in its plural form?","choices":["moose","buffalo","antelope","ox"],"correct":3,"explanation":{"correct":"Answer: ox. The word 'ox' is a singular noun; its plural form is 'oxen'.","incorrect":[{"choice":"moose","category":"irregular plural noun","reason":"Although 'moose' looks singular, it is an irregular noun where the plural form is the same as the singular form (e.g., 'one moose,' 'two moose')."},{"choice":"buffalo","category":"irregular plural noun","reason":"The word 'buffalo' is often used in its plural form without changing its spelling. It can be written as 'buffalo' or 'buffaloes,' but in this context, it functions as a plural noun."},{"choice":"antelope","category":"irregular plural noun","reason":"Like other animal names, 'antelope' is an irregular noun that remains the same in both its singular and plural forms."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":32,"sourceFile":"Advanced-2_grammer and usage.pdf","sourceQuestionNumber":3,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Some nouns have irregular plural forms that do not end in -s or -es, and some do not change their spelling at all when referring to more than one.","example":"one child / two children, one deer / two deer, one ox / two oxen","strategyClue":"Try adding a number before each word and ask yourself if the noun would change form in a sentence (e.g., 'I see one ____'). If the word is 'ox', the plural becomes 'oxen', showing it is the only one in the group that is strictly singular.","link":"","linkText":""}},{"id":"grammar-singular-plural-nouns-q0033","version":3,"contentHash":"sha256:72e3459c86cd037f040dbfb56edfa43676ccda635a94cc1a34360694230935ce","question":"Which is NOT a correct irregular noun?","choices":["two-year- old - two-years- old","child - children","passerby - passersby","parenthesis - parentheses"],"correct":0,"explanation":{"correct":"Answer: two-year-old - two-years-old. In English, when a noun is used as part of a compound adjective before a noun, it must be singular. You would say a 'two-year-old child,' never a 'two-years-old child.'","incorrect":["",{"choice":"child - children","category":"irregular plural noun","reason":"This is a correct irregular noun form. 'Children' is the standard irregular plural form for the singular noun 'child', so it is not the answer."},{"choice":"passerby - passersby","category":"irregular plural noun","reason":"This is a correct irregular noun form. For compound words like 'passerby,' the plural ending is added to the main noun, making 'passersby' correct."},{"choice":"parenthesis - parentheses","category":"irregular plural noun","reason":"This is a correct irregular noun form. 'Parentheses' is the standard Greek-based plural form for the singular 'parenthesis,' so it is not the answer."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":33,"sourceFile":"Advanced-3_grammer and usage.pdf","sourceQuestionNumber":7,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Irregular nouns are nouns that do not follow the standard 's' or 'es' rule to become plural, or they behave differently when used in compound phrases.","example":"foot -> feet, mouse -> mice, tooth -> teeth","strategyClue":"Check if the noun changes its form internally, uses a Greek/Latin ending, or if the plural 's' should be placed on the main part of a compound word instead of the end.","link":"","linkText":""}},{"id":"grammar-singular-plural-nouns-q0034","version":2,"contentHash":"sha256:90b317ec51550ca51d42887aa3618e866f5effd94ac0349d44494f298726e58b","question":"Identify the underlined phrase. Soccer, Henry’s favorite sport, has become more popular among American children.","choices":["gerund phrase","participial phrase","infinitive phrase","appositive phrase"],"correct":3,"explanation":{"correct":"Answer: appositive phrase. An appositive is a noun or noun phrase that renames another noun right beside it. In this sentence, 'Henry’s favorite sport' renames the word 'Soccer'.","incorrect":[{"choice":"gerund phrase","category":"gerund phrase error","reason":"A gerund phrase begins with a verb ending in -ing that acts as a noun. 'Henry's favorite sport' does not contain a gerund."},{"choice":"participial phrase","category":"participial phrase error","reason":"A participial phrase acts as an adjective and usually starts with a verb ending in -ing or -ed. This phrase functions as a noun rename, not an adjective."},{"choice":"infinitive phrase","category":"infinitive phrase error","reason":"An infinitive phrase begins with the word 'to' followed by a verb (e.g., 'to run'). This phrase does not contain an infinitive."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":34,"sourceFile":"Advanced-4_grammer and usage.pdf","sourceQuestionNumber":4,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"An appositive phrase is a group of words that explains, renames, or identifies the noun it follows. It is usually set off by commas.","example":"My dog, a golden retriever, is friendly. We visited Paris, the city of lights. My brother, a talented cook, made dinner.","strategyClue":"Check if you can remove the phrase between the commas without losing the main meaning of the sentence. If the sentence still makes sense, the phrase is likely an appositive.","link":"","linkText":""}},{"id":"grammar-singular-plural-nouns-q0035","version":2,"contentHash":"sha256:2dcd908f0664668ebce6b28fc605d28142ed33a396fdc72c7cdacc7128cfd173","question":"Choose the correct sentence.","choices":["I d rived the children to school every morning.","I wants to hang the pictures on the wall.","I hung several pictures on the wall for Jillian.","I hangs several of the pictures on the wall."],"correct":2,"explanation":{"correct":"Answer: I hung several pictures on the wall for Jillian. The verb 'hung' is the correct past tense form of 'hang' used here, and the subject 'I' correctly pairs with this verb form.","incorrect":[{"choice":"I d rived the children to school every morning.","category":"spelling and verb tense","reason":"The word 'd rived' is not a correctly spelled English word. The past tense of 'drive' is 'drove'."},{"choice":"I wants to hang the pictures on the wall.","category":"subject-verb agreement","reason":"The subject 'I' requires the base form of the verb 'want' rather than 'wants', which is only used for third-person singular subjects like 'he' or 'she'."},"",{"choice":"I hangs several of the pictures on the wall.","category":"subject-verb agreement","reason":"The verb 'hangs' is reserved for third-person singular subjects. Since the subject is 'I', the verb should be 'hang'."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":60,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":35,"sourceFile":"Advanced-6_grammer and usage.pdf","sourceQuestionNumber":10,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Verbs must match the subject in number and person, and irregular verbs often change their spelling in the past tense.","example":"Correct: I hang, she hangs, I hung yesterday. Incorrect: I hangs, she hang.","strategyClue":"Test the subject by swapping 'I' for 'he'. If the verb form feels correct with 'he' but wrong with 'I', you have identified a subject-verb agreement mismatch.","link":"","linkText":""}},{"id":"grammar-singular-plural-nouns-q0036","version":3,"contentHash":"sha256:8533e4cab16b74ebbfea5f4a4cac9467389b5dae7b7469eea26910a0490a68d4","question":"Which pair of nouns is NOT correct?","choices":["b eat - beats","truck - trucks","design - designes","signal - signals"],"correct":2,"explanation":{"correct":"Answer: design - designes. This pair is incorrect because the plural of 'design' is 'designs'. To make most nouns plural, you simply add '-s', not '-es'.","incorrect":[{"choice":"b eat - beats","category":"noun pluralization error","reason":"This is a valid plural form. Nouns ending in most consonants just need an 's' at the end to become plural."},{"choice":"truck - trucks","category":"regular noun pluralization","reason":"This is a correct plural. 'Truck' is a regular noun, so adding 's' is the standard way to show there is more than one."},"",{"choice":"signal - signals","category":"regular noun pluralization","reason":"This is a correct plural. Like the others, 'signal' follows the standard rule of adding 's' to show plurality."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":36,"sourceFile":"Basic-1_grammer and usage.pdf","sourceQuestionNumber":6,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"To make most singular nouns plural, simply add an 's' to the end. The '-es' ending is generally reserved for words ending in sounds like 's', 'x', 'z', 'ch', or 'sh'.","example":"dog -> dogs, cat -> cats, bus -> buses (ends in 's'), box -> boxes (ends in 'x')","strategyClue":"Look at the ending of the base noun; if it does not end in a 'hissing' or 'buzzing' sound, try to see if adding 'es' creates a spelling pattern that doesn't follow standard rules.","link":"","linkText":""}},{"id":"grammar-singular-plural-nouns-q0037","version":3,"contentHash":"sha256:25fe5e9e9b8841bb719d9e4b34e8d7988f69e20330b25d6b572e9f3621b5fa1d","question":"Which of the underlined words is NOT correct? The airplanes circled the mountains looking for the wolfs who were preying on the cattle.","choices":["airplanes","mountains","wolfs","cattle"],"correct":2,"explanation":{"correct":"Answer: wolfs. The plural of 'wolf' is 'wolves'. Words ending in '-f' or '-fe' often change the 'f' to 'v' and add '-es' to become plural.","incorrect":[{"choice":"airplanes","category":"plural noun formation","reason":"This word is spelled correctly. It follows the standard rule of adding '-s' to a noun to make it plural."},{"choice":"mountains","reason":"\"mountains\" is a correct noun form, so it is not the incorrect or non-plural choice the prompt asks for."},"",{"choice":"cattle","reason":"\"cattle\" is a correct noun form, so it is not the incorrect or non-plural choice the prompt asks for."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":37,"sourceFile":"Basic-4_grammer and usage.pdf","sourceQuestionNumber":3,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"To make many nouns that end in 'f' or 'fe' plural, you usually drop the 'f' or 'fe' and add 'ves'.","example":"leaf to leaves, knife to knives, shelf to shelves","strategyClue":"Look at the end of each underlined noun. If it ends in 'f' or 'fe', say the plural form aloud to check if it sounds like it should end in 'fs' or 'ves'.","link":"","linkText":""}},{"id":"grammar-singular-plural-nouns-q0038","version":2,"contentHash":"sha256:73df138594f81feee8a2c100190a1e8a4f88199663d69d8f66687a28820890cb","question":"In the sentence below, which word is a plural noun? Our teacher brought three cookies for each student.","choices":["t eacher","brought","cookies","each"],"correct":2,"explanation":{"correct":"Answer: cookies. A plural noun refers to more than one person, place, or thing, and it often ends in an 's'. 'Cookies' is the only word in the list that describes a thing and has an 's' to show there is more than one.","incorrect":[{"choice":"t eacher","category":"singular noun","reason":"The word 'teacher' names a person, but it is a singular noun because there is only one teacher mentioned in the sentence."},{"choice":"brought","category":"verb usage","reason":"'Brought' is an action word, not a noun. Actions show what the subject is doing, while nouns name the things involved."},"",{"choice":"each","category":"determiner error","reason":"'Each' is a word used to point to a singular member of a group. It does not name a person, place, or thing, so it cannot be a noun."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":38,"sourceFile":"Basic-6_grammer and usage.pdf","sourceQuestionNumber":5,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"A plural noun is a word that names more than one person, place, or thing, usually by adding 's' or 'es' to the end of a singular noun.","example":"one cat vs. two cats; one bench vs. two benches; one box vs. many boxes.","strategyClue":"Look for words that name a thing and end with an 's'. Check if you can put the word 'many' in front of it to see if it makes sense as a group of items.","link":"","linkText":""}},{"id":"grammar-singular-plural-nouns-q0039","version":2,"contentHash":"sha256:2bd9ed93034c816d3f49abfa6af9797734ac570bf4f405ced71bbbf1a3400389","question":"Which word is a plural noun? The children are at first recess.","choices":["are","first","recess","children"],"correct":3,"explanation":{"correct":"Answer: children. A plural noun refers to more than one person, place, or thing. 'Children' is the irregular plural form of the singular noun 'child'.","incorrect":[{"choice":"are","category":"verb form","reason":"'Are' is a helping verb used to describe what the children are doing. It is not a noun at all."},{"choice":"first","category":"ordinal adjective","reason":"'First' is an adjective used here to describe the order of the recess period. Adjectives describe nouns; they are not nouns themselves."},{"choice":"recess","category":"singular noun","reason":"'Recess' is a singular noun because it refers to one specific break time. Plural nouns usually show that there is more than one of something."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":40,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":39,"sourceFile":"Basic-7_grammer and usage.pdf","sourceQuestionNumber":7,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"A plural noun is a word that names more than one person, place, or thing. While many plurals end in 's' or 'es', some irregular nouns like 'children' change their spelling completely.","example":"one cat/two cats, one box/two boxes, one child/two children","strategyClue":"Look for a word that acts as the subject of the sentence and ask yourself, 'Does this word mean one thing or more than one thing?' Only pick the word that represents a group.","link":"","linkText":""}},{"id":"grammar-singular-plural-nouns-q0040","version":2,"contentHash":"sha256:57ad4de4aa4ca89e7d9876311637c54b036ac1f955602d9bfac2ba4636b01c4a","question":"Which noun pair has a correct plural form?","choices":["wolf - wolfs","child - children","ox - oxes","mouse - mouses"],"correct":1,"explanation":{"correct":"Answer: child - children. The noun 'child' is an irregular noun that does not follow the standard 's' or 'es' rule for plurals; its plural form is 'children'.","incorrect":[{"choice":"wolf - wolfs","category":"irregular plural error","reason":"When a noun ends in 'f' or 'fe', we often change the ending to 'ves' to make it plural. The correct plural for 'wolf' is 'wolves'."},"",{"choice":"ox - oxes","category":"incorrect plural suffix","reason":"While many words add 'es', 'ox' is an irregular noun. The correct plural form is 'oxen', not 'oxes'."},{"choice":"mouse - mouses","category":"irregular vowel change","reason":"Most irregular nouns that change their spelling don't just add an 's'. 'Mouse' changes its internal vowels to become 'mice' in the plural form."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":40,"sourceFile":"Proficient-1_grammer and usage.pdf","sourceQuestionNumber":5,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Regular plurals add -s or -es to the end of a word, but irregular nouns change their spelling in special ways.","example":"dog -> dogs, box -> boxes, man -> men, goose -> geese","strategyClue":"Test the word by imagining it in a sentence with 'many'. Ask yourself if the word sounds natural with just an 's' added, or if you recognize it as a word that changes its internal spelling.","link":"","linkText":""}},{"id":"grammar-singular-plural-nouns-q0041","version":3,"contentHash":"sha256:97760f83ad24b4aeecbde01bb48e64df396a4cb6b209c7f7e11e04ee8bae08e4","question":"Which of the word pairs below does NOT include both the correct singular and plural form of the same noun?","choices":["man - men","child - children","knife - knifes","wolf - wolves"],"correct":2,"explanation":{"correct":"Answer: knife - knifes. This pair is incorrect because the plural of 'knife' follows the rule of changing 'f' or 'fe' to 'ves'. The correct plural form is 'knives', not 'knifes'.","incorrect":[{"choice":"man - men","category":"irregular plural noun","reason":"This pair is correct. 'Men' is the correct irregular plural form of the singular noun 'man'."},{"choice":"child - children","category":"irregular plural noun","reason":"This pair is correct. 'Children' is the correct irregular plural form of the singular noun 'child'."},"",{"choice":"wolf - wolves","category":"f to ves change","reason":"This pair is correct. Nouns ending in 'f' often change to 'ves' in the plural, making 'wolves' the correct form of 'wolf'."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":41,"sourceFile":"Proficient-2_grammer and usage.pdf","sourceQuestionNumber":4,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"While most nouns become plural by adding 's' or 'es', some nouns have irregular spellings, and many nouns ending in 'f' or 'fe' change their ending to 'ves'.","example":"man/men, child/children, leaf/leaves, life/lives","strategyClue":"Test each pair by saying the singular noun and then trying to identify its plural. If you find a pair where the plural form looks like it simply added an 's' to a word ending in 'f', check if that word actually belongs to the 'ves' spelling group.","link":"","linkText":""}},{"id":"grammar-singular-plural-nouns-q0042","version":2,"contentHash":"sha256:0a0d50b11223852683c642d6be10626d79053209d1095e164956fa60e75be7a0","question":"Which of the following is a plural noun?","choices":["gorilla","dress","man","fences"],"correct":3,"explanation":{"correct":"Answer: fences. The word 'fences' is the plural form of 'fence' because it adds an '-es' ending to show that there is more than one.","incorrect":[{"choice":"gorilla","category":"singular noun","reason":"The word 'gorilla' refers to only one animal. To make it plural, we would need to add an 's' to the end."},{"choice":"dress","category":"singular noun","reason":"The word 'dress' is singular. Because it ends in 'ss', the plural form would require adding '-es' to become 'dresses'."},{"choice":"man","category":"irregular plural noun","reason":"The word 'man' is a singular noun. Its plural form is 'men', which is an irregular plural that changes the spelling rather than just adding an 's'."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":42,"sourceFile":"Proficient-4_grammer and usage.pdf","sourceQuestionNumber":8,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"A plural noun represents more than one person, place, or thing. Most nouns become plural by adding 's' or 'es' to the end.","example":"cat -> cats, box -> boxes, cherry -> cherries","strategyClue":"Try adding the word 'many' or 'two' before the noun. If the word needs an 's' or 'es' ending to sound correct with 'many', it is likely the plural form.","link":"","linkText":""}},{"id":"grammar-singular-plural-nouns-q0043","version":2,"contentHash":"sha256:4d381fda5b6a04bb5c166261641ab5d045c7dab35c87d99069a26d57d5918326","question":"Which set of nouns has the correct plural form?","choices":["st ory - story","man - mans","alphabet - alphabet","woman - women"],"correct":3,"explanation":{"correct":"Answer: woman - women. Some English nouns are irregular, meaning they don't follow the 's' or 'es' rule. Changing the vowel 'a' to 'e' is the correct way to make 'woman' plural.","incorrect":[{"choice":"st ory - story","category":"incorrect plural formation","reason":"This option shows a singular word and its singular form; to make 'story' plural, you must change the 'y' to 'ies', resulting in 'stories'."},{"choice":"man - mans","category":"irregular plural error","reason":"The word 'man' is an irregular noun. Adding an 's' to make it 'mans' is incorrect; the correct plural form follows the same pattern as 'woman', which is 'men'."},{"choice":"alphabet - alphabet","category":"missing plural indicator","reason":"This choice lists the singular form twice. To make 'alphabet' plural, you must add 's' to create the word 'alphabets'."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":43,"sourceFile":"Proficient-5_grammer and usage.pdf","sourceQuestionNumber":3,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"While most nouns become plural by adding 's' or 'es', some irregular nouns change their internal vowels or spelling entirely.","example":"foot - feet, child - children, mouse - mice","strategyClue":"Check if the noun ends in a letter you would normally add 's' to. If it doesn't look right, ask yourself if the noun is an irregular type that changes its middle sound instead.","link":"","linkText":""}},{"id":"grammar-singular-plural-nouns-q0044","version":3,"contentHash":"sha256:68e2c3bf47bbe07624e5b03d38c01730fa0151b5b15fc58601c13e3446940f43","question":"Which underlined word is NOT a plural noun? Six dogs with rawhide bones followed the boy into the trees.","choices":["boy","dogs","bones","trees"],"correct":0,"explanation":{"correct":"Answer: boy. A plural noun refers to more than one of something and usually ends in -s or -es. 'Boy' refers to only one person, making it a singular noun.","incorrect":["",{"choice":"dogs","category":"plural noun identification","reason":"The word 'dogs' ends in -s and refers to more than one animal, so it is a plural noun."},{"choice":"bones","category":"plural noun identification","reason":"Because 'bones' refers to more than one object and ends with an -s, it functions as a plural noun in this sentence."},{"choice":"trees","category":"plural noun identification","reason":"The word 'trees' represents more than one of the plant, which makes it a plural noun."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":44,"sourceFile":"Proficient-6_grammer and usage.pdf","sourceQuestionNumber":3,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"A singular noun names one person, place, or thing, while a plural noun names more than one, often by adding -s or -es to the end.","example":"Singular: cat, box, boy. Plural: cats, boxes, boys.","strategyClue":"Try putting the number 'one' in front of the word; if it makes sense, it is singular. If the word needs a higher number like 'six' to make sense, it is plural.","link":"","linkText":""}},{"id":"grammar-singular-plural-nouns-q0045","version":2,"contentHash":"sha256:5aab939495cc62287ebfd8201fa50e5eb89ed9add49a7fa7e07a8ba0039fff98","question":"Choose the correct words to complete the sentence. Romance _____ in the library ________ the favorite choice for the girls.","choices":["b ook, is","book, are","books, are","books, is"],"correct":2,"explanation":{"correct":"Answer: books, are. The noun 'books' is plural, so it requires the plural verb 'are'. Because the subject 'books' is plural, the verb must match it to maintain subject-verb agreement.","incorrect":[{"choice":"b ook, is","category":"singular noun and verb","reason":"The sentence implies more than one item, so 'book' should be pluralized as 'books', and 'is' is only used for singular subjects."},{"choice":"book, are","category":"singular noun disagreement","reason":"While 'are' is a plural verb, 'book' is singular. Subjects and verbs must agree in number; you need a plural noun to match the plural verb."},"",{"choice":"books, is","category":"subject-verb disagreement","reason":"The noun 'books' is plural, but 'is' is a singular verb. You must use 'are' to correctly match the plural subject."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":45,"sourceFile":"Proficient-7_grammer and usage.pdf","sourceQuestionNumber":5,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"Subject-verb agreement means that if a noun is plural (more than one), the verb must also be in its plural form.","example":"The dog runs (singular). The dogs run (plural). The cake is good (singular). The cakes are good (plural).","strategyClue":"First, look at the noun to see if it ends in 's' or represents more than one. Then, test the verb by asking yourself, 'Does this action word match the number of the noun?'","link":"","linkText":""}},{"id":"grammar-singular-plural-nouns-q0046","version":3,"contentHash":"sha256:52ccb0083b2db5489043091b30d8e289b25993b47e4d851fb974a1ba8b0f4f7e","question":"Which of the following words is NOT plural?","choices":["mice","girl","gentlemen","ladies"],"correct":1,"explanation":{"correct":"Answer: girl. The word 'girl' is singular because it refers to only one person. Adding an 's' or changing the spelling to 'mice' or 'gentlemen' creates a plural form.","incorrect":[{"choice":"mice","category":"irregular plural noun","reason":"The word 'mice' is the plural form of 'mouse'. Because it refers to more than one, it is not the correct answer."},"",{"choice":"gentlemen","category":"irregular plural noun","reason":"The word 'gentlemen' is the plural form of 'gentleman'. Since it names more than one person, it is a plural noun."},{"choice":"ladies","category":"plural with -ies","reason":"The word 'ladies' is the plural form of 'lady'. It ends in '-ies' to show that there is more than one, so it is a plural noun."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"medium","5":"medium","6":"medium"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"use the source question clue and compare each answer choice to the rule","estimatedTimeSeconds":50,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":46,"sourceFile":"Proficient-7_grammer and usage.pdf","sourceQuestionNumber":9,"testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]},"studyAid":{"definition":"A singular noun refers to one person, place, or thing, while a plural noun refers to more than one.","example":"Singular: cat, child, tooth. Plural: cats, children, teeth.","strategyClue":"Ask yourself: 'If I had this object in my hand, would I have only one, or would I have a group?' If you can only have one, it is singular.","link":"","linkText":""}},{"id":"grammar-singular-plural-nouns-q0047","version":3,"contentHash":"sha256:4e4076768aca0975c3d45d1d7074952e1fb4b0eef5678b7eebeeb805e260bd28","question":"Which noun is NOT in its plural form?","choices":["dice","deer","cactus","mice"],"correct":2,"explanation":{"correct":"Answer: cactus. This word is in its singular form. To make it plural, we typically change it to 'cacti' or 'cactuses'.","incorrect":[{"choice":"dice","category":"irregular plural noun","reason":"The word 'dice' is already a plural noun (the singular form is 'die')."},{"choice":"deer","category":"irregular plural noun","reason":"'Deer' is a special noun that stays the same in both singular and plural forms."},"",{"choice":"mice","category":"irregular plural noun","reason":"'Mice' is the plural form of the word 'mouse'."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":47,"sourceFile":"Advanced-1_language Usage.pdf","sourceQuestionNumber":19,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"A singular noun refers to one item, while a plural noun refers to more than one item, often formed by adding -s, -es, or changing the word entirely.","example":"cat/cats, child/children, goose/geese, sheep/sheep","strategyClue":"Test each word by asking, 'Can I have one of these?' If you can have one, it is singular. If you need two or more, it is plural.","link":"","linkText":""}},{"id":"grammar-singular-plural-nouns-q0048","version":2,"contentHash":"sha256:b083e0195ea4b2822477491366e38d4c600defc536dfc379c053243359667049","question":"Which noun is plural? The herdof deer is running though the man’s vegetable garden.","choices":["herd","deer","man’s","garden"],"correct":1,"explanation":{"correct":"Answer: deer. 'Deer' is an irregular plural noun, meaning it stays the same in both its singular and plural forms. In this context, it refers to the group of animals.","incorrect":[{"choice":"herd","category":"collective noun","reason":"The word 'herd' is a singular collective noun representing a group, not the plural of an animal."},"",{"choice":"man’s","category":"possessive noun","reason":"The apostrophe and 's' show ownership, meaning the garden belongs to a single man; it is a singular possessive noun."},{"choice":"garden","category":"singular common noun","reason":"The word 'garden' refers to one single place, as shown by the article 'the' and the lack of an '-s' suffix."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":48,"sourceFile":"Advanced-1_language Usage.pdf","sourceQuestionNumber":31,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"While most nouns add '-s' or '-es' to become plural, some irregular nouns stay exactly the same whether they are singular or plural.","example":"One deer / two deer, one sheep / three sheep, one fish / ten fish","strategyClue":"Try adding 'one' or 'many' before the word. If the word doesn't change even when you use 'many,' it is an irregular plural noun.","link":"","linkText":""}},{"id":"grammar-singular-plural-nouns-q0049","version":2,"contentHash":"sha256:f1d5930b8a84fbd06c6e263ec93ee56f4b02f3b329f4dae4559f5f412be46adf","question":"What does the underlined expression mean? You need to make a decision soon or you are going to miss the boat.","choices":["miss going on vacation","be too late","not be able to have fun","lose your job"],"correct":1,"explanation":{"correct":"Answer: be too late. The idiom 'miss the boat' means that someone has missed an opportunity because they were too slow to act.","incorrect":[{"choice":"miss going on vacation","category":"literal interpretation","reason":"This is a literal interpretation of the word 'boat'. Idioms are phrases that have a hidden, figurative meaning rather than a literal one."},"",{"choice":"not be able to have fun","category":"vague meaning","reason":"While missing an opportunity might make someone sad, this choice is too broad. The specific meaning of the idiom refers to losing out on a chance by waiting too long."},{"choice":"lose your job","category":"too specific","reason":"This choice is too specific. You could 'miss the boat' on many things besides a job, such as buying tickets or joining a team."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":49,"sourceFile":"Advanced-2_language Usage.pdf","sourceQuestionNumber":42,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"An idiom is a phrase where the meaning cannot be understood just by looking at the individual words. 'Miss the boat' is a common idiom meaning you missed your chance to do something.","example":"If you don't apply for the contest today, you will miss the boat. / Don't wait too long to buy your tickets, or you might miss the boat.","strategyClue":"Ask yourself if the words are being used in their literal, dictionary sense or if they represent a broader idea. Try replacing the idiom with a phrase about 'missing an opportunity' to see if it makes sense.","link":"","linkText":""}},{"id":"grammar-singular-plural-nouns-q0050","version":2,"contentHash":"sha256:422bf1bc31a4c33bf47c0b57abf5b58dac8bed12fbd6fdf0186695ff641703b6","question":"What is the plural of hero?","choices":["heros","hero","heroes","hero’s"],"correct":2,"explanation":{"correct":"Answer: heroes. When a noun ends in a consonant followed by 'o', you usually add '-es' to make it plural.","incorrect":[{"choice":"heros","category":"incorrect plural spelling","reason":"Simply adding an 's' to this word is incorrect. Nouns ending in 'o' often require the '-es' ending to show plurality."},{"choice":"hero","category":"singular noun form","reason":"This is the singular form of the word. Since we are looking for the plural form, we must change the ending."},"",{"choice":"hero’s","category":"possessive noun error","reason":"The apostrophe indicates possession (belonging to the hero), not plurality. Do not use an apostrophe when you just want to talk about more than one hero."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"hard","5":"hard","6":"hard"},"primaryDifficulty":"hard","intrinsicDifficulty":"hard","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":65,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":50,"sourceFile":"Advanced-2_language Usage.pdf","sourceQuestionNumber":44,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"To make most nouns that end in a consonant followed by 'o' plural, you add '-es'.","example":"hero becomes heroes, tomato becomes tomatoes, potato becomes potatoes","strategyClue":"Look at the letter right before the 'o'. If it is a consonant, test adding '-es' instead of just '-s' to see if it follows the standard spelling rule.","link":"","linkText":""}},{"id":"grammar-singular-plural-nouns-q0051","version":2,"contentHash":"sha256:bf28fd19d0ad9c802e587ecc02933f66a8e68d1bf202dfdaef0d24e9f697fbd7","question":"These words can be put together to make a sentence. you me my can help with homework Choose the complete sentence below, using all of these words.","choices":["Help me can you with my homework?","Homework with me can you help?","Can you help me with my homework?","With you my homework can help me?"],"correct":2,"explanation":{"correct":"Answer: Can you help me with my homework?. A complete sentence usually starts with an uppercase letter, includes a clear subject and verb in the correct order, and ends with proper punctuation like a question mark.","incorrect":[{"choice":"Help me can you with my homework?","category":"Incorrect word order","reason":"Starting with 'Help' makes this a command, but the rest of the sentence doesn't follow the correct pattern for a question. Questions about ability should begin with the helping verb 'Can'."},{"choice":"Homework with me can you help?","category":"Confused sentence structure","reason":"This places 'Homework' at the front, which doesn't make sense here. Always put the subject ('you') near the action ('help') to keep the meaning clear."},"",{"choice":"With you my homework can help me?","category":"Incorrect subject placement","reason":"This version suggests the homework is doing the helping! In English, place the person you are talking to ('you') as the subject of the question."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"passage-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":51,"sourceFile":"Basic-1_language Usage.pdf","sourceQuestionNumber":4,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"A sentence is a group of words that expresses a complete thought. It needs a subject (who or what) and a predicate (the action) in an order that makes sense.","example":"Correct: Can you run fast? Incorrect: Fast you can run?","strategyClue":"Try to identify the 'action' word and the 'person' doing it. In a question, look for the helping verb at the beginning and check if the word order creates a logical request.","link":"","linkText":""}},{"id":"grammar-singular-plural-nouns-q0052","version":4,"contentHash":"sha256:078a750a840f03159fac521b50897f6f522f84dc2915ca3e2c6b8813d1649393","question":"Choose the best missing word. The cook put carrots and celery in the soup. I do not like _______.","choices":["they","its","our","them"],"correct":3,"explanation":{"correct":"Answer: them. We use the objective pronoun 'them' because it receives the action of the verb 'like' and refers to the plural nouns 'carrots and celery'.","incorrect":[{"choice":"they","category":"subject pronoun usage","reason":"'They' is a subject pronoun used to perform an action. Since the carrots and celery are being talked about in the objective case after the verb 'like', 'they' is incorrect."},{"choice":"its","category":"possessive pronoun error","reason":"'Its' is used to show ownership, not to replace the object of a sentence. Also, 'its' is singular, but we are talking about two vegetables."},{"choice":"our","category":"possessive adjective error","reason":"'Our' shows possession and requires a noun to follow it, such as 'our soup'. It cannot replace the plural nouns 'carrots and celery' on its own."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":52,"sourceFile":"Basic-1_language Usage.pdf","sourceQuestionNumber":19,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Objective pronouns replace nouns that receive the action in a sentence. Common objective pronouns include me, you, him, her, it, us, and them.","example":"I saw him (correct) vs. I saw he (incorrect). We ate them (correct) vs. We ate they (incorrect).","strategyClue":"Identify the noun phrase being replaced and determine if it is acting as the subject of the sentence or the object receiving the action.","link":"https://www.thecorestandards.org/ELA-Literacy/","linkText":"Common Core ELA standards"}},{"id":"grammar-singular-plural-nouns-q0053","version":2,"contentHash":"sha256:b57f374c3269ad244c6e8622d3235364b0fd06cd8cf6d4b4f95dcfa000964d3b","question":"Which word means more than one?","choices":["foot","mouse","man","geese"],"correct":3,"explanation":{"correct":"Answer: geese. This word is the irregular plural form of 'goose,' meaning more than one bird of this type.","incorrect":[{"choice":"foot","category":"singular noun","reason":"'Foot' refers to only one part of the body. The plural form is 'feet'."},{"choice":"mouse","category":"singular noun","reason":"'Mouse' refers to a single small rodent. To describe more than one, you would use the word 'mice'."},{"choice":"man","category":"singular noun","reason":"'Man' refers to one person. The plural form is 'men'."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":53,"sourceFile":"Basic-1_language Usage.pdf","sourceQuestionNumber":31,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"Most English nouns add 's' or 'es' to show there is more than one, but some nouns change their spelling entirely to become plural.","example":"goose vs. geese, child vs. children, tooth vs. teeth","strategyClue":"Ask yourself: 'If I have a whole group of these, what word do I use to describe them?' If the word doesn't end in an 's' or 'es', check if it is one of the special irregular plural words.","link":"","linkText":""}},{"id":"grammar-singular-plural-nouns-q0054","version":2,"contentHash":"sha256:6d20ea5892aa2bdee94ed7f38c0d97788a109040bd0c555fdfd44405ad9aab41","question":"What is the plural of fork?","choices":["forkes","forks","fork’s","for kk es"],"correct":1,"explanation":{"correct":"Answer: forks. To make most nouns plural, you simply add an 's' to the end of the word.","incorrect":[{"choice":"forkes","category":"incorrect plural spelling","reason":"Adding '-es' is usually reserved for words ending in sounds like 'ch', 'sh', 's', or 'x'. Since 'fork' ends in a 'k' sound, a simple '-s' is all that is needed."},"",{"choice":"fork’s","category":"misplaced apostrophe","reason":"An apostrophe followed by an 's' shows possession (belonging to the fork), not plurality (more than one fork). Remove the punctuation to show there is more than one."},{"choice":"for kk es","category":"spelling error","reason":"This spelling incorrectly changes the base word 'fork' by doubling the 'k' and adding unnecessary spaces. Always keep the base word the same when adding the plural ending."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"easy","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","writing","language usage"],"feedbackFocus":"use the writing or language-usage clue and compare each answer choice to the rule","estimatedTimeSeconds":45,"reviewPriority":"normal","sourceSet":"grammar-singular-plural-nouns","sequence":54,"sourceFile":"Basic-2_language Usage.pdf","sourceQuestionNumber":44,"sourceCategory":"language-usage-test","testFocus":["MAP"],"Test focus":["MAP"],"skillIds":["grammar.usage","grammar.writing"],"standardIds":["L.3-6.1","W.3-6.5"]},"studyAid":{"definition":"A plural noun names more than one person, place, or thing. You can usually make a noun plural by adding 's' to the end.","example":"cat -> cats, dog -> dogs, fork -> forks","strategyClue":"Look at the ending of the noun. If the word does not end in 's', 'x', 'z', 'ch', or 'sh', try adding just an 's' to the very end without changing the spelling of the base word.","link":"","linkText":""}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, then nearby grade-appropriate practice to fill the configured mission length"}}}
  );
})();
